        return fmt.Errorf("bid %s already exists", bidID)
    }

    // Check auction is still open
    auctionStatus, _ := ctx.GetStub().GetState("AUCTION_STATUS_" + auctionID

# Security Analysis of vuln_03_goroutine.go

## Executive Summary

This chaincode contains **critical non-determinism vulnerabilities** caused by improper use of goroutines. Hyperledger Fabric requires deterministic execution across all endorsing peers—goroutines violate this fundamental requirement and will cause endorsement failures and potential consensus issues.

---

## Vulnerabilities Identified

### 1. Non-Deterministic Goroutine Execution in TallyVotes

| Attribute | Details |
|-----------|---------|
| **Type** | Non-Deterministic Operation |
| **Severity** | Critical |
| **Location** | `TallyVotes()` function, lines 68-90 |

**Description:**
The function spawns goroutines to read proposal states concurrently. Goroutine scheduling is non-deterministic—different peers execute `GetState` calls in different orders, producing different read-set orderings. Even with mutex protection, the order of map population varies.

```go
go func(id string) {
    defer wg.Done()
    proposalJSON, err := ctx.GetStub().GetState(id)  // Non-deterministic order
    // ...
    mu.Lock()
    results[id] = proposal.VoteCount  // Map iteration order also non-deterministic
    mu.Unlock()
}(pid)
```

**Impact:**
- Endorsement mismatch between peers
- Transaction validation failures
- Potential consensus divergence

**Recommended Fix:**
```go
func (v *VotingContract) TallyVotes(ctx contractapi.TransactionContextInterface, proposalIDs []string) error {
    results := make(map[string]int)

    // Process sequentially in deterministic order
    for _, pid := range proposalIDs {
        proposalJSON, err := ctx.GetStub().GetState(pid)
        if err != nil {
            return fmt.Errorf("failed to read proposal %s: %v", pid, err)
        }
        if proposalJSON == nil {
            continue
        }

        var proposal Proposal
        if err := json.Unmarshal(proposalJSON, &proposal); err != nil {
            return fmt.Errorf("failed to unmarshal proposal %s: %v", pid, err)
        }
        results[pid] = proposal.VoteCount
    }

    summaryJSON, err := json.Marshal(results)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState("TALLY_RESULT", summaryJSON)
}
```

---

### 2. Concurrent PutState Calls in BatchUpdateStatus

| Attribute | Details |
|-----------|---------|
| **Type** | Non-Deterministic Operation / Unsafe Stub Access |
| **Severity** | Critical |
| **Location** | `BatchUpdateStatus()` function, lines 95-130 |

**Description:**
Multiple goroutines call `PutState` concurrently. The Fabric stub is **not thread-safe**—concurrent writes cause undefined behavior and different write-set orderings across peers.

```go
go func(id string) {
    // ...
    err = ctx.GetStub().PutState(id, updatedJSON)  // Concurrent stub access
}(pid)
```

**Impact:**
- Data corruption in write-set
- Endorsement failures
- Unpredictable ledger state

**Recommended Fix:**
```go
func (v *VotingContract) BatchUpdateStatus(ctx contractapi.TransactionContextInterface, proposalIDs []string, newStatus string) error {
    for _, pid := range proposalIDs {
        proposalJSON, err := ctx.GetStub().GetState(pid)
        if err != nil {
            return fmt.Errorf("failed to read proposal %s: %v", pid, err)
        }
        if proposalJSON == nil {
            continue
        }

        var proposal Proposal
        if err := json.Unmarshal(proposalJSON, &proposal); err != nil {
            return fmt.Errorf("failed to unmarshal proposal %s: %v", pid, err)
        }
        proposal.Status = newStatus

        updatedJSON, err := json.Marshal(proposal)
        if err != nil {
            return fmt.Errorf("failed to marshal proposal %s: %v", pid, err)
        }
        if err := ctx.GetStub().PutState(pid, updatedJSON); err != nil {
            return fmt.Errorf("failed to update proposal %s: %v", pid, err)
        }
    }
    return nil
}
```

---

### 3. Fire-and-Forget Goroutine with Stub Access

| Attribute | Details |
|-----------|---------|
| **Type** | Non-Deterministic Operation / Resource Leak |
| **Severity** | Critical |
| **Location** | `AsyncNotify()` function, lines 133-147 |

**Description:**
A detached goroutine accesses the stub after the main function returns. The stub lifecycle is tied to the transaction—accessing it from a background goroutine after transaction completion causes undefined behavior.

```go
go func() {
    // May execute after transaction completes
    ctx.GetStub().SetEvent("NOTIFY", eventData)  // Stub may be invalid
}()
return nil  // Function returns immediately
```

**Impact:**
- Event may or may not be emitted
- Different peers produce different event sets
- Potential panic or memory corruption

**Recommended Fix:**
```go
func (v *VotingContract) AsyncNotify(ctx contractapi.TransactionContextInterface, proposalID string, message string) error {
    payload := map[string]string{
        "proposal": proposalID,
        "message":  message,
    }
    eventData, err := json.Marshal(payload)
    if err != nil {
        return fmt.Errorf("failed to marshal event: %v", err)
    }

    // Synchronous event emission
    return ctx.GetStub().SetEvent("NOTIFY", eventData)
}
```

---

### 4. Missing Duplicate Vote Prevention

| Attribute | Details |
|-----------|---------|
| **Type** | Access Control / Business Logic Flaw |
| **Severity** | High |
| **Location** | `CastVote()` function, lines 43-62 |

**Description:**
The function appends voters to a list but never checks if a voter has already voted. This allows vote manipulation.

```go
// No check for existing voter
proposal.VoteCount++
proposal.Voters = append(proposal.Voters, voterID)
```

**Recommended Fix:**
```go
func (v *VotingContract) CastVote(ctx contractapi.TransactionContextInterface, proposalID string, voterID string) error {
    // ... existing validation ...

    // Check for duplicate vote
    for _, existingVoter := range proposal.Voters {
        if existingVoter == voterID {
            return fmt.Errorf("voter %s has already voted on proposal %s", voterID, proposalID)
        }
    }

    proposal.VoteCount++
    proposal.Voters = append(proposal.Voters, voterID)
    // ...
}
```

---

### 5. Ignored JSON Unmarshal Errors

| Attribute | Details |
|-----------|---------|
| **Type** | Input Validation |
| **Severity** | Medium |
| **Location** | Multiple functions (lines 51, 79, 109) |

**Description:**
`json.Unmarshal` errors are ignored, allowing corrupted data to cause silent failures.

```go
json.Unmarshal(proposalJSON, &proposal)  // Error ignored
```

**Recommended Fix:**
```go
if err := json.Unmarshal(proposalJSON, &proposal); err != nil {
    return fmt.Errorf("failed to unmarshal proposal: %v", err)
}
```

