## Recommended Fixes

### Fix for Global Variable Issues

Replace global variables with ledger-stored state:

```go
// Remove global variables entirely
// var transactionCounter int    // DELETE
// var lastProcessedID string    // DELETE

// SystemState stores counters on the ledger
type SystemState struct {
    TransactionCounter int    `json:"transactionCounter"`
    LastProcessedID    string `json:"lastProcessedID"`
}

const systemStateKey = "SYSTEM_STATE"

// getSystemState retrieves the system state from the ledger
func (t *TokenContract) getSystemState(ctx contractapi.TransactionContextInterface) (*SystemState, error) {
    stateJSON, err := ctx.GetStub().GetState(systemStateKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read system state: %v", err)
    }

    state := &SystemState{}
    if stateJSON != nil {
        if err := json.Unmarshal(stateJSON, state); err != nil {
            return nil, fmt.Errorf("failed to unmarshal system state: %v", err)
        }
    }
    return state, nil
}

// saveSystemState persists the system state to the ledger
func (t *TokenContract) saveSystemState(ctx contractapi.TransactionContextInterface, state *SystemState) error {
    stateJSON, err := json.Marshal(state)
    if err != nil {
        return fmt.Errorf("failed to marshal system state: %v", err)
    }
    return ctx.GetStub().PutState(systemStateKey, stateJSON)
}

// IssueToken - Fixed version
func (t *TokenContract) IssueToken(ctx contractapi.TransactionContextInterface, owner string, amount float64) error {
    // Input validation
    if owner == "" {
        return fmt.Errorf("owner cannot be empty")
    }
    if amount <= 0 {
        return fmt.Errorf("amount must be positive")
    }

    // Access control - verify caller is admin
    if err := t.verifyAdmin(ctx); err != nil {
        return err
    }

    // Get counter from ledger (deterministic)
    sysState, err := t.getSystemState(ctx)
    if err != nil {
        return err
    }

    sysState.TransactionCounter++
    sysState.LastProcessedID = owner

    token := Token{
        Owner:   owner,
        Balance: amount,
        TxCount: sysState.TransactionCounter,
        LastTx:  "ISSUE",
    }

    tokenJSON, err := json.Marshal(token)
    if err != nil {
        return err
    }

    if err := ctx.GetStub().PutState(owner, tokenJSON); err != nil {
        return err
    }

    return t.saveSystemState(ctx, sysState)
}
```

