    }

    // Update with incremented version
    fromAccount.Balance -= amount
    fromAccount.Version++

    toBytes, _ := ctx.GetStub().Get

# Security Vulnerability Analysis

## Vulnerability Report

### 1. Resource Leak - Iterator Not Closed on Early Return (ProcessClaimsByRange)

| Attribute | Details |
|-----------|---------|
| **Type** | Resource Leak / Denial of Service |
| **Severity** | High |
| **Location** | `ProcessClaimsByRange`, lines 35-43 |

**Description:**
The function opens an iterator via `GetStateByRange()`, then performs a counting loop to check if any claims exist. If no claims are found, it returns an error on line 43 **before** the `defer resultsIterator.Close()` statement on line 47 is registered. In Go, `defer` statements are only registered when execution reaches them—if the function returns before the `defer` line, the cleanup never occurs.

```go
resultsIterator, err := ctx.GetStub().GetStateByRange(startKey, endKey)
// ... counting loop ...
if claimCount == 0 {
    return fmt.Errorf("no claims found...")  // ← Returns BEFORE defer is registered
}
defer resultsIterator.Close()  // ← Never executed if early return occurs
```

**Impact:** Leaked gRPC streams accumulate, eventually exhausting peer resources and causing denial of service.

**Recommended Fix:**
```go
resultsIterator, err := ctx.GetStub().GetStateByRange(startKey, endKey)
if err != nil {
    return fmt.Errorf("failed to get state by range: %v", err)
}
defer resultsIterator.Close()  // ← Place immediately after successful open

claimCount := 0
for resultsIterator.HasNext() {
    claimCount++
    resultsIterator.Next()
}
if claimCount == 0 {
    return fmt.Errorf("no claims found in range %s to %s", startKey, endKey)
}
```

---

### 2. Conditional Resource Leak (GetHighValueClaims)

| Attribute | Details |
|-----------|---------|
| **Type** | Resource Leak / Denial of Service |
| **Severity** | High |
| **Location** | `GetHighValueClaims`, lines 66-91 |

**Description:**
The iterator is only closed inside the `else` branch (when threshold ≤ 0). On the normal execution path where `threshold > 0`, the function iterates through results and returns without ever calling `Close()`. Additionally, if `resultsIterator.Next()` returns an error inside the loop, the function returns immediately, also leaking the iterator.

```go
if threshold > 0 {
    for resultsIterator.HasNext() {
        queryResult, err := resultsIterator.Next()
        if err != nil {
            return nil, err  // ← Leaked iterator
        }
        // ...
    }
    // ← No Close() on this path
} else {
    resultsIterator.Close()  // ← Only closed in error branch
    return nil, fmt.Errorf("threshold must be positive")
}
return highValue, nil  // ← Iterator leaked on normal path
```

**Recommended Fix:**
```go
resultsIterator, err := ctx.GetStub().GetStateByRange(startKey, endKey)
if err != nil {
    return nil, fmt.Errorf("failed to query range: %v", err)
}
defer resultsIterator.Close()  // ← Always close via defer

if threshold <= 0 {
    return nil, fmt.Errorf("threshold must be positive, got %d", threshold)
}

var highValue []*Claim
for resultsIterator.HasNext() {
    queryResult, err := resultsIterator.Next()
    if err != nil {
        return nil, err
    }
    var claim Claim
    json.Unmarshal(queryResult.Value, &claim)
    if claim.Amount >= threshold {
        highValue = append(highValue, &claim)
    }
}
return highValue, nil
```

---

### 3. Manual Close Bypassed on Early Return (ArchiveOldClaims)

| Attribute | Details |
|-----------|---------|
| **Type** | Resource Leak / Denial of Service |
| **Severity** | High |
| **Location** | `ArchiveOldClaims`, lines 97-122 |

**Description:**
The function relies on a manual `Close()` call at the end of the function instead of using `defer`. Multiple early return paths exist:
1. If `resultsIterator.Next()` returns an error (line 106)
2. If the batch limit of 100 is reached (line 116)

Both paths return without closing the iterator.

```go
resultsIterator, err := ctx.GetStub().GetStateByRange(...)
// No defer Close()

for resultsIterator.HasNext() {
    queryResult, err := resultsIterator.Next()
    if err != nil {
        return archived, err  // ← Leaked
    }
    // ...
    if archived >= 100 {
        return archived, nil  // ← Leaked
    }
}
resultsIterator.Close()  // ← Only reached if loop completes normally
```

**Recommended Fix:**
```go
resultsIterator, err := ctx.GetStub().GetStateByRange(prefix+"_0000", prefix+"_9999")
if err != nil {
    return 0, err
}
defer resultsIterator.Close()  // ← Guaranteed cleanup

archived := 0
for resultsIterator.HasNext() {
    queryResult, err := resultsIterator.Next()
    if err != nil {
        return archived, err
    }
    // ... processing logic ...
    if archived >= 100 {
        return archived, nil  // ← Safe: defer will close
    }
}
return archived, nil
```

---

### 4. Unchecked JSON Marshal Error (ProcessClaimsByRange)

| Attribute | Details |
|-----------|---------|
| **Type** | Error Handling Flaw |
| **Severity** | Low |
| **Location** | `ProcessClaimsByRange`, line 68 |

**Description:**
The `json.Marshal` error is silently ignored with `_`. While unlikely to fail for this struct, ignoring errors can mask data corruption issues.

```go
updatedJSON, _ := json.Marshal(claim)  // ← Error ignored
```

**Recommended Fix:**
```go
updatedJSON, err := json.Marshal(claim)
if err != nil {
    return fmt.Errorf("failed to marshal claim %s: %v", claim.ClaimID, err)
}
```

---

## Summary

| # | Vulnerability | Severity | Function |
|---|--------------|----------|----------|
| 1 | Defer placed after early return | High | ProcessClaimsByRange |
| 2 | Iterator closed only in else branch | High | GetHighValueClaims |
| 3 | Manual close bypassed by early returns | High | ArchiveOldClaims |
| 4 | Ignored marshal error | Low | ProcessClaimsByRange |

**Key Pattern:** All three high-severity vulnerabilities stem from improper iterator lifecycle management. The canonical fix is to **always place `defer iterator.Close()` immediately after successfully opening the iterator**, before any validation or processing logic that might return early.

# Security Analysis of vuln_03_goroutine.go

## Executive Summary

This chaincode contains **critical non-determinism vulnerabilities** caused by improper use of goroutines. Hyperledger Fabric requires deterministic execution across all endorsing peers—goroutines violate this fundamental requirement and will cause endorsement failures or unpredictable behavior.

---

## Vulnerabilities Identified

### 1. Non-Deterministic Goroutine Execution in TallyVotes

| Attribute | Details |
|-----------|---------|
| **Type** | Non-Deterministic Operation |
| **Severity** | **Critical** |
| **Location** | `TallyVotes()` function, lines 68-89 |

**Description:**
The function spawns goroutines to read proposal states concurrently. Goroutine scheduling is non-deterministic—different peers execute `GetState` calls in different orders, producing different read-set orderings. Even with mutex protection for the `results` map, the underlying stub interactions occur in unpredictable sequences.

```go
go func(id string) {
    defer wg.Done()
    proposalJSON, err := ctx.GetStub().GetState(id)  // Non-deterministic order
    // ...
    mu.Lock()
    results[id] = proposal.VoteCount
    mu.Unlock()
}(pid)
```

**Impact:** Endorsement mismatch between peers; transaction validation failures.

**Recommended Fix:**
```go
func (v *VotingContract) TallyVotes(ctx contractapi.TransactionContextInterface, proposalIDs []string) error {
    results := make(map[string]int)

    // Process sequentially to ensure deterministic execution
    for _, pid := range proposalIDs {
        proposalJSON, err := ctx.GetStub().GetState(pid)
        if err != nil {
            return fmt.Errorf("failed to read proposal %s: %v", pid, err)
        }
        if proposalJSON == nil {
            continue
        }

        var proposal Proposal
        if err := json.Unmarshal(proposalJSON, &proposal); err != nil {
            return fmt.Errorf("failed to unmarshal proposal %s: %v", pid, err)
        }
        results[pid] = proposal.VoteCount
    }

    summaryJSON, err := json.Marshal(results)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState("TALLY_RESULT", summaryJSON)
}
```

